#!/usr/bin/env python3
"""Guest and missing-OAuth UI checks on an explicitly selected emulator; no account is fabricated."""
import importlib.util,time
from pathlib import Path
import argparse
a=argparse.ArgumentParser();a.add_argument('--serial',required=True);args=a.parse_args()
p=Path(__file__).with_name('smoke-commerce.py');s=importlib.util.spec_from_file_location('commerce',p);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);v=m.CommerceSmoke(args.serial);v.launch();v.home();v.click('Settings');v.click('Account');ns=v.nodes();labels=[m.BASE.text(n) for n in ns];assert 'Playing as a guest' in labels;assert any('OAuth and Firebase' in x for x in labels);v.click('Sign in with Google');time.sleep(.3);assert 'Playing as a guest' in [m.BASE.text(n) for n in v.nodes()];v.screenshot('account');v.shell('input','keyevent','4');v.click('Français');v.click('Compte');assert 'Connexion avec Google' in [m.BASE.text(n) for n in v.nodes()] or any('Google' in m.BASE.text(n) for n in v.nodes());v.screenshot('account-fr');v.shell('input','keyevent','4');v.click('English');v.shell('input','keyevent','4');assert 'FATAL EXCEPTION' not in v.shell('logcat','-d','-b','crash');(v.root/'docs/validation/lab/identity-ui.txt').write_text('PASS installed Lab Settings -> Account in English and French.\nPASS guest default, no owner configuration, explanatory OAuth/Firebase notice.\nPASS Google button with absent configuration preserves guest state; no fake login, wallet grant or ad opt-in.\nPASS English restored, crash buffer clean.\nNOT VALIDATED: actual Google account selection, Firebase sign-in/sign-out or deletion; matching OAuth/Firebase configuration is absent.\n');print('PASS optional account guest/configuration guards EN/FR; no actual Google login claimed.')
